function serviceScore(customers){const sv=servers();const ck=cooks();const labor=sv.reduce((a,w)=>{const assign=w.assignment==='salon'?1.18:w.assignment==='barra'?1.08:w.assignment==='recepcion'?1.02:.9;const swift=w.abilityId==='swift'?1.12:1;return a+(w.service*.055+w.speed*.035)*workerEfficiency(w)*assign*swift},0)+ck.reduce((a,w)=>a+w.speed*.012*workerEfficiency(w),0)+state.upgrades.kitchen*1.45+(hasAbility('warm')?1.8:0);const coverage=(hasPost('salon')?1:0)+(hasPost('barra')?.6:0);return clamp(.4+coverage*.08+labor/Math.max(16,customers*2.6),.35,1.3)}
