function renderFocus(){const w=selectedWorker();if(!w)return;$('#focusName').textContent=w.name;$('#focusRole').textContent=w.roleLabel;$('#focusSprite').src=w.portrait||w.sprite;$('#focusMood').textContent=mood(w);$('#focusLevel').textContent=`Nv. ${w.level}`;$('#focusWage').textContent=w.wage;$('#focusEnergy').textContent=Math.round(w.energy);$('#focusMorale').textContent=Math.round(w.morale);$('#focusLoyalty').textContent=Math.round(w.loyalty??60);$('#focusRarity').textContent=w.rarity||'Común';$('#focusRarity').className=`rarity-tag ${w.rarityClass||'common'}`;$('#focusAssignment').textContent=assignmentLabel(w.assignment);$('#focusDuty').textContent=w.active?'En turno':'Descanso';$('#focusDuty').className=`status-chip ${w.active?'good':'off'}`;$('#focusAbility').textContent=w.ability||'Sin habilidad especial';$('#focusAbilityText').textContent=w.abilityText||'Trabajadora generalista.';$('#focusTrait').textContent=w.trait||'Profesional';const need=w.level*100;$('#focusXp').textContent=`${w.xp}/${need}`;$('#focusXpBar').style.width=`${Math.min(100,w.xp/need*100)}%`;$('#focusStats').innerHTML=statBars(w);$('#assignmentOptions').innerHTML=validPosts(w).map(p=>`<button class="assignment-choice ${w.assignment===p&&w.active?'active':''}" data-post="${p}"><b>${POST_DEFS[p].short}</b><span>${POST_DEFS[p].label}</span></button>`).join('');document.querySelectorAll('[data-post]').forEach(b=>b.onclick=()=>setAssignment(w.id,b.dataset.post));$('#restBtn').textContent=w.active?'Descansar':'Volver al turno';$('#dismissBtn').disabled=state.staff.length<=1}
function statBars(w){return[['Servicio','service'],['Carisma','charisma'],['Velocidad','speed'],['Resistencia','stamina']].map(([l,k])=>`<div class="stat-row"><span>${l}</span><div class="bar"><i style="width:${w[k]}%"></i></div><b>${w[k]}</b></div>`).join('')}
function renderScene(){const title=state.reputation>=60?'Posada legendaria':state.reputation>=35?'Taberna célebre':state.reputation>=20?'Taberna concurrida':'Taberna humilde';$('#tavernTitle').textContent=title;$('#capacity').textContent=capacity();$('#activeStaffCount').textContent=activeStaff().length;$('#wages').textContent=wages();$('#demandLabel').textContent=demandModifier()>1.08?'Alta':demandModifier()<.82?'Baja':'Normal';const svc=serviceScore(Math.max(5,capacity())),ready=operationalReadiness();$('#serviceBadge').textContent=ready.score>=90&&svc>=.95?'Operación excelente':ready.score>=70&&svc>=.72?'Servicio estable':'Cobertura incompleta';$('#serviceBadge').className=`status-chip ${ready.score>=70&&svc>=.72?'good':''}`;$('#sceneStatus').textContent=state.lastDay?`Última jornada · ${state.lastDay.visitors} clientes · ${state.lastDay.net>=0?'+':''}${state.lastDay.net} oro netos · preparación ${state.lastDay.readiness??ready.score}%.`:'Salón cerrado. Asigna puestos antes de la primera jornada.';$('#sceneStaff').innerHTML=activeStaff().slice(0,8).map((w,i)=>`<button class="scene-worker post-${w.assignment} slot-${i}" data-worker="${w.id}" title="${w.name} · ${assignmentLabel(w.assignment)}"><img src="${w.portrait||w.sprite}" alt="${w.name}"><span>${w.name}</span><small>${assignmentLabel(w.assignment)}</small></button>`).join('');const crowd=state.lastDay?.visitors||0;$('#tavernScene').dataset.crowd=crowd>capacity()*.75?'high':crowd>capacity()*.35?'mid':'low';$('#sceneClients').innerHTML=crowd?`<div class="crowd-meter"><span>Último aforo</span><b>${crowd}/${capacity()}</b><i style="width:${Math.min(100,crowd/capacity()*100)}%"></i></div>`:'';$('#sceneShift').innerHTML=activeStaff().length?`<span>${activeStaff().length} en turno</span><span>${state.staff.length-activeStaff().length} descansando</span>`:'<span>Sin personal en turno</span>';const posts=['salon','barra','cocina','recepcion','despensa'];$('#postBoard').innerHTML=posts.map(p=>{const workers=staffAt(p),covered=workers.length>0;return`<button class="post-cell ${covered?'covered':'missing'}" data-jump-post="${p}"><span>${POST_DEFS[p].short}</span><div><b>${POST_DEFS[p].label}</b><small>${covered?workers.map(w=>w.name).join(', '):'Sin cubrir'}</small></div><strong>${covered?'OPERATIVO':'VACANTE'}</strong></button>`}).join('');document.querySelectorAll('[data-worker]').forEach(b=>b.onclick=()=>selectWorker(b.dataset.worker));document.querySelectorAll('[data-jump-post]').forEach(b=>b.onclick=()=>{const w=staffAt(b.dataset.jumpPost)[0];if(w)selectWorker(w.id);switchTab('staff')})}
function renderSummary(){const d=state.lastDay,ready=operationalReadiness();$('#lastDayBadge').textContent=d?`Día ${d.day}`:'Sin abrir';$('#todayKpis').innerHTML=d?`<div><span>Ingresos</span><b class="positive">+${d.revenue}</b></div><div><span>Gastos</span><b class="negative">-${d.expenses}</b></div><div><span>Beneficio</span><b class="${d.net>=0?'positive':'negative'}">${d.net>=0?'+':''}${d.net}</b></div><div><span>Clientes</span><b>${d.visitors}</b></div>`:'<div><span>Abre la primera jornada</span><b>—</b></div>';$('#aleStockMini').textContent=state.ale;$('#foodStockMini').textContent=state.food;$('#cellarLevelMini').textContent=state.upgrades.cellar;$('#forecastBadge').textContent=state.forecast.label;$('#forecastText').textContent=state.forecast.text;$('#financeChart').innerHTML=chartSvg(state.financeHistory);const warnings=[];if(state.ale<5||state.food<4)warnings.push('inventario bajo');if(activeStaff().some(w=>w.energy<30))warnings.push('personal exhausto');if(ready.missing.length)warnings.push(`sin cubrir: ${ready.missing.map(assignmentLabel).join(', ')}`);$('#openHint').textContent=warnings.length?`Atención · ${warnings.join(' · ')}`:`Operación preparada al ${ready.score}%. Inventario y puestos listos.`}
function chartSvg(history){const data=history.slice(-8);if(!data.length)return'<div style="display:grid;place-items:center;height:100%;color:#8f8172">Aún no hay jornadas registradas.</div>';const W=600,H=160,pad=18,max=Math.max(...data.flatMap(d=>[d.revenue,d.expenses,Math.abs(d.net)]),10);const xs=i=>pad+i*((W-pad*2)/Math.max(1,data.length-1)),ys=v=>H-pad-(v/max)*(H-pad*2),path=k=>data.map((d,i)=>`${i?'L':'M'}${xs(i)},${ys(Math.max(0,k==='net'?d.net:d[k]))}`).join(' ');return`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><path class="chart-grid" d="M18 40H582M18 80H582M18 120H582"/><path class="chart-income" d="${path('revenue')}"/><path class="chart-expense" d="${path('expenses')}"/><path class="chart-profit" d="${path('net')}"/></svg>`}
